**`app/app/pipeline/page.tsx:203-205` — setTimeout sin cleanup**

```typescript
if (nuevoEstado === "oferta") {
  setCelebracion(true);
  setTimeout(() => setCelebracion(false), 4000); // leak si el componente desmonta
}
```

**Solución:**

```typescript
const celebracionTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

// En moverCandidatura:
if (nuevoEstado === "oferta") {
  setCelebracion(true);
  if (celebracionTimerRef.current) clearTimeout(celebracionTimerRef.current);
  celebracionTimerRef.current = setTimeout(() => setCelebracion(false), 4000);
}

// Cleanup en el componente:
useEffect(() => () => {
  if (celebracionTimerRef.current) clearTimeout(celebracionTimerRef.current);
}, []);
```

